package de.feldexa.app.storage

import java.nio.charset.StandardCharsets
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * T027 review-correction tests for the local canonical JSON encoder.
 *
 * The store re-serializes revision content before it persists and hashes it,
 * while the Dart client hashes `canonicalJsonBytes` (canonical tree +
 * `jsonEncode`) and later verifies the native receipt. The two encoders must
 * therefore emit identical bytes for every value the revision model allows.
 *
 * The expected strings below were generated by the actual Dart 3.13.5
 * `canonicalJsonEncode` for the same values. They pin the shortest-round-trip
 * form, the fixed/exponential thresholds, the trailing `.0` on integral
 * doubles above 2^53, lowercase `e`, explicit `+` exponents, subnormals, and
 * negative zero.
 */
class CanonicalJsonTest {

    @Test
    fun doublesMatchDartCanonicalJsonBytes() {
        val cases: List<Pair<String, Pair<Double, String>>> = listOf(
            "positive zero" to (0.0 to "0"),
            "negative zero" to (-0.0 to "0"),
            "integral one" to (1.0 to "1"),
            "integral minus one" to (-1.0 to "-1"),
            "simple fraction" to (1.5 to "1.5"),
            "negative fraction" to (-1.5 to "-1.5"),
            "one tenth" to (0.1 to "0.1"),
            "negative one tenth" to (-0.1 to "-0.1"),
            "three decimals" to (0.001 to "0.001"),
            "small fraction" to (0.000123 to "0.000123"),
            "fixed lower threshold" to (1e-6 to "0.000001"),
            "exponential below threshold" to (1e-7 to "1e-7"),
            "negative exponential" to (-1e-7 to "-1e-7"),
            "ten micrometres" to (1e-5 to "0.00001"),
            "short exponent fraction" to (1.5e-7 to "1.5e-7"),
            "negative short exponent" to (-2.5e-7 to "-2.5e-7"),
            "fixed upper threshold" to (1e20 to "100000000000000000000.0"),
            "exponential upper threshold" to (1e21 to "1e+21"),
            "exponential upper plus one" to (1e22 to "1e+22"),
            "large fixed mantissa" to (1.2e20 to "120000000000000000000.0"),
            "large exponent mantissa" to (1.23e21 to "1.23e+21"),
            "exact 2^53" to (9007199254740992.0 to "9007199254740992"),
            "above 2^53" to (9007199254740994.0 to "9007199254740994.0"),
            "max double" to (
                1.7976931348623157e308 to "1.7976931348623157e+308"
            ),
            "min subnormal" to (5e-324 to "5e-324"),
            "min normal" to (
                2.2250738585072014e-308 to "2.2250738585072014e-308"
            ),
            "near min normal" to (
                2.225073858507201e-308 to "2.225073858507201e-308"
            ),
            "seventeen digits" to (
                1.2345678901234567 to "1.2345678901234567"
            ),
            "binary artifact" to (0.30000000000000004 to "0.30000000000000004"),
            "four significant digits" to (1.005 to "1.005"),
            "pi" to (3.141592653589793 to "3.141592653589793"),
            "negative large fraction" to (
                -6235002124039.308 to "-6235002124039.308"
            ),
            "all nines" to (
                999999999999999900000.0 to "999999999999999900000.0"
            ),
            "just above threshold" to (
                1.0000000000000001e21 to "1.0000000000000001e+21"
            ),
            "large fixed" to (
                123456789012345680.0 to "123456789012345680.0"
            ),
            "larger fixed" to (
                1234567890123456800.0 to "1234567890123456800.0"
            ),
            "long exponent" to (
                1.0000000000000002e-7 to "1.0000000000000002e-7"
            ),
            "negative long exponent" to (
                -1.0000000000000002e-7 to "-1.0000000000000002e-7"
            ),
            "integral 1e16" to (1e16 to "10000000000000000.0"),
            "integral 1e17" to (1e17 to "100000000000000000.0"),
            "integral 1e18" to (1e18 to "1000000000000000000.0"),
            "integral 1e19" to (1e19 to "10000000000000000000.0"),
            "integral 1e15" to (1e15 to "1000000000000000"),
        )

        for ((name, testCase) in cases) {
            val (value, expected) = testCase
            val actual = CanonicalJson.encodeToString(linkedMapOf("v" to value))
            assertEquals("Dart canonical bytes for $name", "{\"v\":$expected}", actual)
        }
    }

    @Test
    fun parsedDartBytesReencodeToTheSameBytes() {
        val encoded = listOf(
            "{\"v\":1e-7}",
            "{\"v\":-1.0000000000000002e-7}",
            "{\"v\":0.000001}",
            "{\"v\":100000000000000000000.0}",
            "{\"v\":1e+21}",
            "{\"v\":9007199254740994.0}",
            "{\"v\":5e-324}",
            "{\"v\":1.7976931348623157e+308}",
        )

        for (text in encoded) {
            val bytes = text.toByteArray(StandardCharsets.UTF_8)
            val parsed = CanonicalJson.parse(bytes)
            assertEquals(text, CanonicalJson.encodeToString(parsed))
        }
    }

    @Test
    fun nestedMapsSortKeysAndPreserveArrayOrderWithDartNumbers() {
        val value = linkedMapOf<String, Any?>(
            "z" to 1.0000000000000002e-7,
            "a" to listOf(1e21, 1.0, -0.0),
            "m" to linkedMapOf<String, Any?>("b" to 1e-7, "a" to 1.5),
        )

        assertEquals(
            "{\"a\":[1e+21,1,0],\"m\":{\"a\":1.5,\"b\":1e-7}," +
                "\"z\":1.0000000000000002e-7}",
            CanonicalJson.encodeToString(value),
        )
    }
}
